    estado character varying(20) NOT NULL,
    id_condominio integer NOT NULL,
    id_usuario_condominio_admin integer NOT NULL,
    tipo character varying(20) DEFAULT 'GENERAL'::character varying NOT NULL,
    total_habilitados integer,
    votos_requeridos integer,
    CONSTRAINT ck_votacion_fechas CHECK ((fecha_fin >= fecha_inicio)),
    CONSTRAINT ck_votaciones_tipo CHECK (((tipo)::text = ANY ((ARRAY['GENERAL'::character varying, 'CAMBIO_CUOTA'::character varying, 'CAMBIO_ROL'::character varying])::text[]))),
    CONSTRAINT votaciones_estado_check CHECK (((estado)::text = ANY ((ARRAY['ABIERTA'::character varying, 'CERRADA'::character varying])::text[])))
);


