    dia_limite_propuesto integer DEFAULT 10 NOT NULL,
    estado_propuesta character varying(20) DEFAULT 'PENDIENTE'::character varying NOT NULL,
    periodo_aplicacion character varying(20) NOT NULL,
    motivo text,
    fecha_ejecucion timestamp without time zone,
    CONSTRAINT votaciones_cambio_cuota_dia_limite_propuesto_check CHECK (((dia_limite_propuesto >= 1) AND (dia_limite_propuesto <= 28))),
    CONSTRAINT votaciones_cambio_cuota_estado_propuesta_check CHECK (((estado_propuesta)::text = ANY ((ARRAY['PENDIENTE'::character varying, 'APROBADA'::character varying, 'RECHAZADA'::character varying, 'EJECUTADA'::character varying])::text[]))),
    CONSTRAINT votaciones_cambio_cuota_monto_propuesto_check CHECK ((monto_propuesto > (0)::numeric)),
    CONSTRAINT votaciones_cambio_cuota_recargo_propuesto_check CHECK ((recargo_propuesto >= (0)::numeric))
);


